select * from cr_report_score


        and `status` = #{listQuery.status}


        and `subject` = #{listQuery.subject}


        and `submit_time` >= #{listQuery.startTime}


        and `submit_time` <= #{listQuery.endTime}



        and (`rater_name` like #{name} or `report_name` like #{name})

select `subject`, count(`subject`) as count
from cr_report_score
GROUP BY `subject`;

select `status`, count(`status`) as count
from cr_report_score
GROUP BY `status`;
